// user.cpp
//
// Fixes the RELEASE-only crash in /app/main.cpp (the DEBUG build was already
// clean) and removes the remaining memory leak in both modes.
//
// Root cause
// ----------
// This system's in-house libstdc++ (see
// /build/libstdc++-v3/src/c++98/locale_init.cc and
// /build/libstdc++-v3/include/bits/locale_classes.tcc) adds an MSVC-style
// facet registry: every call to std::__try_use_facet() invokes
// std::_Facet_Register_impl(), which on its FIRST call allocates 5 registry
// nodes. In RELEASE builds (-DNDEBUG) those nodes are allocated through the
// global operator new, which main.cpp overrides to use its own 10 MB
// bump-allocator heap that is destroyed at exit (Application::shutdown()).
// The registry's static destructor then runs at exit - AFTER the custom heap
// has been freed - and deletes nodes that live inside the freed 10 MB region,
// which glibc's free() rejects and the process dies with SIGSEGV. The DEBUG
// build allocates the nodes with std::malloc directly, so it exits cleanly.
//
// The second defect (valgrind leak in BOTH modes): the in-house libstdc++
// mallocs an exception emergency pool at startup (libsupc++/eh_alloc.cc)
// and never frees it; the only function that does so,
// __gnu_cxx::__freeres(), is never called by the library.
//
// The fix
// -------
// 1. user_init() forces the one-shot facet registration to run NOW, i.e.
//    BEFORE main.cpp installs the custom heap, by touching a standard facet.
//    From that point on the global operator new/delete fall through to
//    malloc/free, so the registry nodes live on the ordinary heap and are
//    freed correctly at exit.
// 2. user_cleanup() calls __gnu_cxx::__freeres() so the startup exception
//    pool is released and Valgrind reports no leaks.

#include "user.h"

#include <cstdlib>
#include <locale>

// In-house libstdc++ helper: frees the emergency exception pool that was
// allocated with malloc at startup (see eh_alloc.cc). It is a strong symbol
// of the linked libstdc++, so it resolves from the archive.
namespace __gnu_cxx
{
void __freeres() noexcept;
}

namespace
{

// Touches a standard facet of the classic locale, which forces the
// in-house one-shot facet-registry registration (std::_Facet_Register_impl,
// hooked into std::__try_use_facet) to happen immediately. The classic
// locale's own setup uses placement-new on static storage, so the only
// allocations performed here are the registry nodes themselves.
void
force_facet_registry_setup()
{
    const std::ctype<char>* facet =
        &std::use_facet<std::ctype<char> >(std::locale::classic());
    (void) facet;
}

} // namespace

void
user_init()
{
    // Register the locale facet registry now, while the global
    // operator new is still the default malloc-based one (main.cpp
    // installs its custom heap only after user_init() returns).
    force_facet_registry_setup();
}

void
user_cleanup()
{
    // Release the library's startup exception pool so no heap block
    // remains allocated when the process exits.
    __gnu_cxx::__freeres();
}

void
user_main()
{
}
