#include <cstdlib>
#include <cstring>
#include <iostream>
#include <new>
#include <locale>

// ---- main.cpp globals (unmodifiable, but I can reference them) ----
extern void* operator new(std::size_t);
extern void operator delete(void*) noexcept;
extern void operator delete(void*, std::size_t) noexcept;

// A bump-heap sentinel to detect which allocation path is active.
// main.cpp's g_custom_heap is a global; I mirror its effect by checking
// whether global operator new lands in a fresh region.

// The library's marker + flags live in an anonymous namespace of
// locale_init.cc, so I can't read them directly. Instead I'll use the
// observable behavior: if I allocate a chunk via global operator new
// HERE and later check whether it is still "reachable" after the
// custom heap is installed, I can infer which path was taken.
//
// Simpler: just print a marker and see the order via ASAN-free means.
// I'll use a global int that I bump, and a static destructor that
// reports it, to establish relative order with libstdc++'s statics.

static volatile int g_probe_count = 0;
static volatile int g_probe_atexit_count = 0;

struct ProbeOrder {
    ProbeOrder() {
        // record a tag at construction
        static int tag = 0;
        tag++;
        g_probe_count = tag;
        // Also: allocate via global operator new to see the path
        void* p = ::operator new(32);
        // stash
