#include "user.h"
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <locale>
#include <new>

// Read the in-house libstdc++'s facet-registry state. These are anonymous-
// namespace globals defined in locale_init.cc (src/c++98), mangled with the
// _GLOBAL__N_1 prefix. We alias their exact mangled symbols so we can read
// the stored pointer/flag values safely (reading a BSS variable, not deref).
namespace
{
  // fac_head_alias[0..8) == value of _Fac_head (a _Fac_node*)
  char fac_head_raw[8] __attribute__((alias("_ZN12_GLOBAL__N_19_Fac_headE")));
  // fac_reg_alias == value of _Facets_registered (bool/int)
  int fac_reg_raw __attribute__((alias("_ZN12_GLOBAL__N_118_Facets_registeredE")));
  // fac_initc_alias == value of _Static_init_complete (bool/int)
  int fac_initc_raw __attribute__((alias("_ZN12_GLOBAL__N_121_Static_init_completeE")));
}

static void dump_state(const char* where)
{
    void* head = *reinterpret_cast<void**>(fac_head_raw);
    std::cerr << "[diag] " << where
              << " _Fac_head=" << head
              << " _Facets_registered=" << fac_reg_raw
              << " _Static_init_complete=" << fac_initc_raw << std::endl;
}

void user_init()
{
    dump_state("user_init:before");
    // Force the one-shot facet registration now, before main.cpp installs
    // the custom heap.
    const std::ctype<char>* f =
        &std::use_facet<std::ctype<char> >(std::locale::classic());
    (void) f;
    dump_state("user_init:after use_facet");
}

void user_cleanup()
{
    dump_state("user_cleanup");
}

void user_main() {}
